(*==============================================================================
 * PRG_Axis_Control — 运动独立任务（AxisTask）
 * 仅通过 GVL_AxisCmd 输入 / GVL_AxisFb 输出；禁止被外部 CALL
 * 轴绑定：Axis=M1, Axis_1=M2, Axis_2=Y, Axis_3=Z
 *============================================================================*)

(* X 双驱速度合成 *)
fbXDiff(
	eMode := AxisCmd_eXMode,
	eDiffFunc := AxisCmd_eDiffFunc,
	xJogSyncPos := AxisCmd_xJogXSyncPos,
	xJogSyncNeg := AxisCmd_xJogXSyncNeg,
	xJogDiffPos := AxisCmd_xJogXDiffPos,
	xJogDiffNeg := AxisCmd_xJogXDiffNeg,
	xStop := AxisCmd_xStopAll,
	xEnable := AxisCmd_xPower,
	rJogVel := AxisCmd_rJogVelX,
	rDiffDelta := AxisCmd_rDiffDelta,
	rTurnOmega := AxisCmd_rTurnOmega,
	rWheelBase := AxisCmd_rWheelBase
);
xPair := fbXDiff.xUsePairVel;

IF xPair THEN
	(* 成对模式：用 FB_XDiff 输出的有符号速度 *)
	fbM1(
		Axis := _MC_Axis[1],
		xEnable := AxisCmd_xPower,
		xJogPos := FALSE, xJogNeg := FALSE,
		xStop := AxisCmd_xStopAll,
		xResetFault := AxisCmd_xResetFault,
		xHome := FALSE,
		xUseVelCmd := TRUE,
		rVelCmd := fbXDiff.rVelCmdM1,
		rJogVel := AxisCmd_rJogVelX,
		rAcc := AxisCmd_rAcc,
		rDec := AxisCmd_rDec
	);
	fbM2(
		Axis := _MC_Axis[2],
		xEnable := AxisCmd_xPower,
		xJogPos := FALSE, xJogNeg := FALSE,
		xStop := AxisCmd_xStopAll,
		xResetFault := AxisCmd_xResetFault,
		xHome := FALSE,
		xUseVelCmd := TRUE,
		rVelCmd := fbXDiff.rVelCmdM2,
		rJogVel := AxisCmd_rJogVelX,
		rAcc := AxisCmd_rAcc,
		rDec := AxisCmd_rDec
	);
	AxisFb_rVelCmdM1 := fbXDiff.rVelCmdM1;
	AxisFb_rVelCmdM2 := fbXDiff.rVelCmdM2;
ELSE
	(* 独立模式：两侧各自 JOG *)
	fbM1(
		Axis := _MC_Axis[1],
		xEnable := AxisCmd_xPower,
		xJogPos := AxisCmd_xJogM1Pos,
		xJogNeg := AxisCmd_xJogM1Neg,
		xStop := AxisCmd_xStopAll,
		xResetFault := AxisCmd_xResetFault,
		xHome := FALSE,
		xUseVelCmd := FALSE,
		rVelCmd := 0.0,
		rJogVel := AxisCmd_rJogVelX,
		rAcc := AxisCmd_rAcc,
		rDec := AxisCmd_rDec
	);
	fbM2(
		Axis := _MC_Axis[2],
		xEnable := AxisCmd_xPower,
		xJogPos := AxisCmd_xJogM2Pos,
		xJogNeg := AxisCmd_xJogM2Neg,
		xStop := AxisCmd_xStopAll,
		xResetFault := AxisCmd_xResetFault,
		xHome := FALSE,
		xUseVelCmd := FALSE,
		rVelCmd := 0.0,
		rJogVel := AxisCmd_rJogVelX,
		rAcc := AxisCmd_rAcc,
		rDec := AxisCmd_rDec
	);
	AxisFb_rVelCmdM1 := 0.0;
	AxisFb_rVelCmdM2 := 0.0;
	IF AxisCmd_xJogM1Pos THEN AxisFb_rVelCmdM1 := AxisCmd_rJogVelX; END_IF;
	IF AxisCmd_xJogM1Neg THEN AxisFb_rVelCmdM1 := -AxisCmd_rJogVelX; END_IF;
	IF AxisCmd_xJogM2Pos THEN AxisFb_rVelCmdM2 := AxisCmd_rJogVelX; END_IF;
	IF AxisCmd_xJogM2Neg THEN AxisFb_rVelCmdM2 := -AxisCmd_rJogVelX; END_IF;
END_IF;

(* Y / Z *)
fbY(
	Axis := _MC_Axis[3],
	xEnable := AxisCmd_xPower,
	xJogPos := AxisCmd_xJogYPos,
	xJogNeg := AxisCmd_xJogYNeg,
	xStop := AxisCmd_xStopAll,
	xResetFault := AxisCmd_xResetFault,
	xHome := AxisCmd_xHomeY,
	xUseVelCmd := FALSE,
	rVelCmd := 0.0,
	rJogVel := AxisCmd_rJogVelY,
	rAcc := AxisCmd_rAcc,
	rDec := AxisCmd_rDec
);
fbZ(
	Axis := _MC_Axis[4],
	xEnable := AxisCmd_xPower,
	xJogPos := AxisCmd_xJogZPos,
	xJogNeg := AxisCmd_xJogZNeg,
	xStop := AxisCmd_xStopAll,
	xResetFault := AxisCmd_xResetFault,
	xHome := AxisCmd_xHomeZ,
	xUseVelCmd := FALSE,
	rVelCmd := 0.0,
	rJogVel := AxisCmd_rJogVelZ,
	rAcc := AxisCmd_rAcc,
	rDec := AxisCmd_rDec
);

(* ---------- 写反馈区（仅本任务可写） ---------- *)
AxisFb_rPosM1 := fbM1.rActPos;
AxisFb_rPosM2 := fbM2.rActPos;
AxisFb_rPosY := fbY.rActPos;
AxisFb_rPosZ := fbZ.rActPos;
AxisFb_xMovingM1 := fbM1.xMoving;
AxisFb_xMovingM2 := fbM2.xMoving;
AxisFb_xMovingY := fbY.xMoving;
AxisFb_xMovingZ := fbZ.xMoving;
AxisFb_xPoweredM1 := fbM1.xPowered;
AxisFb_xPoweredM2 := fbM2.xPowered;
AxisFb_xPoweredY := fbY.xPowered;
AxisFb_xPoweredZ := fbZ.xPowered;
AxisFb_xFaultM1 := fbM1.xFault;
AxisFb_xFaultM2 := fbM2.xFault;
AxisFb_xFaultY := fbY.xFault;
AxisFb_xFaultZ := fbZ.xFault;
AxisFb_xHomedY := fbY.xHomed;
AxisFb_xHomedZ := fbZ.xHomed;
AxisFb_xStandstill1 := fbM1.xStandstill;
AxisFb_xStandstill2 := fbM2.xStandstill;
AxisFb_xStandstillY := fbY.xStandstill;
AxisFb_xStandstillZ := fbZ.xStandstill;
AxisFb_xReady := NOT (fbM1.xFault OR fbM2.xFault OR fbY.xFault OR fbZ.xFault);

(*==============================================================================
 * FB_XDiff — 龙门 X 双驱速度合成（仅 Axis 任务内使用）
 * eMode: 0=独立  1=同步同速平移  2=差速（子功能见 eDiffFunc）
 * eDiffFunc: 0=纠偏  1=原地旋转(一正一反)  2=差速拐弯
 * 跨距 rWheelBase: 4..6 m；X 运动方向与 Y 垂直
 *============================================================================*)

(* 输出清零 *)
rVelCmdM1 := 0.0;
rVelCmdM2 := 0.0;
xUsePairVel := FALSE;
xActive := FALSE;
(* 跨距合法性 *)
xWheelBaseOk := (rWheelBase >= 4.0) AND (rWheelBase <= 6.0);

(* 未使能 / 停止 / 独立模式：不合成成对速度 *)
IF NOT xEnable OR xStop OR eMode = 0 THEN
	RETURN;
END_IF;

(* ---------- Sync：两侧同速，龙门沿 X 平移 ---------- *)
IF eMode = 1 THEN
	IF xJogSyncPos XOR xJogSyncNeg THEN
		xUsePairVel := TRUE;
		xActive := TRUE;
		IF xJogSyncPos THEN
			rVelCmdM1 := rJogVel;
		ELSE
			rVelCmdM1 := -rJogVel;
		END_IF;
		rVelCmdM2 := rVelCmdM1; (* 同速 *)
	END_IF;
	RETURN;
END_IF;

(* ---------- Diff：需有方向键 ---------- *)
IF NOT (xJogDiffPos XOR xJogDiffNeg) THEN
	RETURN;
END_IF;

(* 原地旋转 / 差速拐弯依赖合法跨距 *)
IF (eDiffFunc = 1 OR eDiffFunc = 2) AND NOT xWheelBaseOk THEN
	RETURN;
END_IF;

xUsePairVel := TRUE;
xActive := TRUE;

CASE eDiffFunc OF
	0: (* 纠偏：同向 V±Δ，扶正龙门 *)
		IF xJogDiffPos THEN
			rVelCmdM1 := rJogVel + rDiffDelta;
			rVelCmdM2 := rJogVel - rDiffDelta;
		ELSE
			rVelCmdM1 := -(rJogVel + rDiffDelta);
			rVelCmdM2 := -(rJogVel - rDiffDelta);
		END_IF;

	1: (* 原地旋转：M1/M2 一正一反，转角度 *)
		IF ABS(rTurnOmega) > 1.0E-6 THEN
			rVelCmdM1 := rTurnOmega * rWheelBase * 0.5;
		ELSE
			rVelCmdM1 := rJogVel;
		END_IF;
		rVelCmdM2 := -rVelCmdM1;
		IF xJogDiffNeg THEN
			rVelCmdM1 := -rVelCmdM1;
			rVelCmdM2 := -rVelCmdM2;
		END_IF;

	2: (* 差速拐弯：两侧同向为主，速度差，可边走边弯 *)
		IF ABS(rTurnOmega) > 1.0E-6 THEN
			rVelCmdM1 := rJogVel + rTurnOmega * rWheelBase * 0.5;
			rVelCmdM2 := rJogVel - rTurnOmega * rWheelBase * 0.5;
		ELSE
			rVelCmdM1 := rJogVel + rDiffDelta;
			rVelCmdM2 := rJogVel - rDiffDelta;
		END_IF;
		IF xJogDiffNeg THEN
			rVelCmdM1 := -rVelCmdM1;
			rVelCmdM2 := -rVelCmdM2;
		END_IF;

ELSE
	xUsePairVel := FALSE;
	xActive := FALSE;
END_CASE;

(*==============================================================================
 * PRG_Logic — 许可 / 联锁 / 写 AxisCmd（MainTask）
 * 禁止 CALL PRG_Axis_Control / FB_Servo / FB_XDiff
 *============================================================================*)

(* ---------- 首次运行：默认参数 ---------- *)
IF NOT xBridgeInited THEN
	HMI_rJogVelX := JogVel;
	HMI_rJogVelY := JogVel;
	HMI_rJogVelZ := JogVel;
	HMI_rWheelBase := yLength;
	IF HMI_rWheelBase < 4.0 THEN
		HMI_rWheelBase := 5.0; (* 默认跨距 5m *)
	END_IF;
	HMI_rDiffDelta := 0.08;
	HMI_rTurnOmega := 0.2;
	HMI_eXMode := 1;      (* 默认 Sync *)
	HMI_eDiffFunc := 0;   (* 默认纠偏 *)
	xM5Ready := FALSE;    (* 第5轴未到货 *)
	xBridgeInited := TRUE;
END_IF;

(* ---------- 原面板变量桥接 ----------
 * EStop：面板按下=TRUE → HMI_xEStop 约定未触发=TRUE，故取反
 * StopBtn：停止；ResetBtn：当作长按复位脉冲（若有独立复位钮）
 * StartBtn：使能触发 → HMI_xEnable（上升沿切换使能闩）
 * 触摸屏可直接写 HMI_*，无需经面板桥
 *------------------------------------------------------------------------*)
HMI_xEStop := NOT EStop;
HMI_xStop := StopBtn;
HMI_xEnable := StartBtn;
IF ResetBtn THEN
	HMI_xStopHold3s := TRUE;
ELSE
	HMI_xStopHold3s := FALSE;
END_IF;

(* 前进/后退按当前 X 模式映射到 Sync / Diff / 独立 *)
IF HMI_eXMode = 1 THEN
	HMI_xJogXSyncPos := JogFwd;
	HMI_xJogXSyncNeg := JogBwd;
END_IF;
IF HMI_eXMode = 2 THEN
	HMI_xJogXDiffPos := JogFwd;
	HMI_xJogXDiffNeg := JogBwd;
END_IF;
IF HMI_eXMode = 0 THEN
	HMI_xJogM1Pos := JogFwd;
	HMI_xJogM1Neg := JogBwd;
	HMI_xJogM2Pos := JogFwd;
	HMI_xJogM2Neg := JogBwd;
END_IF;
HMI_xJogYPos := JogRight;
HMI_xJogYNeg := JogLeft;
HMI_xJogZPos := JogUp;
HMI_xJogZNeg := JogDown;
HMI_xHomeReqY := HomeReq;
HMI_xHomeReqZ := HomeReq;
HMI_rJogVelX := JogVel;
HMI_rJogVelY := JogVel;
HMI_rJogVelZ := JogVel;
IF yLength >= 4.0 AND yLength <= 6.0 THEN
	HMI_rWheelBase := yLength;
END_IF;

(* ---------- 急停锁存：HMI_xEStop=FALSE 为触发 ---------- *)
IF NOT HMI_xEStop THEN
	xEStopLatched := TRUE;
END_IF;

(* 长按停止 3s 复位（要求急停已松开） *)
tonHold(IN := HMI_xStop AND HMI_xEStop, PT := T#3S);
xResetPulse := (HMI_xStopHold3s OR tonHold.Q) AND NOT xResetPrev;
xResetPrev := HMI_xStopHold3s OR tonHold.Q;

IF xResetPulse THEN
	xEStopLatched := FALSE;
	AxisCmd_xResetFault := TRUE; (* 一拍：各轴 MC_Reset *)
	xPowerLatched := FALSE; (* 复位后须再触发使能 *)
ELSE
	AxisCmd_xResetFault := FALSE;
END_IF;

(* ---------- Fault / 使能许可 ---------- *)
xFaultAggregate := AxisFb_xFaultM1 OR AxisFb_xFaultM2 OR AxisFb_xFaultY OR AxisFb_xFaultZ;
xEnablePermit := HMI_xEStop AND NOT xEStopLatched AND NOT xFaultAggregate;
eOpMode := 0; (* 本期仅手动 *)

(* 使能触发：HMI_xEnable 上升沿切换闩；无许可则强制下使能 *)
IF NOT xEnablePermit THEN
	xPowerLatched := FALSE;
ELSIF HMI_xEnable AND NOT xEnablePrev THEN
	xPowerLatched := NOT xPowerLatched;
END_IF;
xEnablePrev := HMI_xEnable;

(* ---------- 限位联锁 ---------- *)
xIlk_BlockYPlus := I_xLimYPos;
xIlk_BlockYNeg := I_xLimYNeg;
xIlk_BlockZPlus := I_xLimZPos;
xIlk_BlockZNeg := I_xLimZNeg;
xIlk_BlockYWhenZ := AxisFb_xMovingZ; (* Z 动则禁 Y *)

(* ---------- 写 Axis 命令区 ---------- *)
AxisCmd_xStopAll := xEStopLatched OR NOT HMI_xEStop OR HMI_xStop OR xFaultAggregate;
AxisCmd_xPower := xPowerLatched AND xEnablePermit;

AxisCmd_eXMode := LIMIT(0, HMI_eXMode, 2);
AxisCmd_eDiffFunc := LIMIT(0, HMI_eDiffFunc, 2);
AxisCmd_rDiffDelta := HMI_rDiffDelta;
AxisCmd_rTurnOmega := HMI_rTurnOmega;
AxisCmd_rWheelBase := LIMIT(4.0, HMI_rWheelBase, 6.0);
AxisCmd_rJogVelX := HMI_rJogVelX;
AxisCmd_rJogVelY := HMI_rJogVelY;
AxisCmd_rJogVelZ := HMI_rJogVelZ;
AxisCmd_rAcc := JogACC;
AxisCmd_rDec := JogDEC;
IF AxisCmd_rAcc < 1.0 THEN AxisCmd_rAcc := 100.0; END_IF;
IF AxisCmd_rDec < 1.0 THEN AxisCmd_rDec := 100.0; END_IF;

(* 先清零，再按模式透传（命令源互斥）；JOG 电平 TRUE=移动 FALSE=暂停 *)
AxisCmd_xJogM1Pos := FALSE; AxisCmd_xJogM1Neg := FALSE;
AxisCmd_xJogM2Pos := FALSE; AxisCmd_xJogM2Neg := FALSE;
AxisCmd_xJogXSyncPos := FALSE; AxisCmd_xJogXSyncNeg := FALSE;
AxisCmd_xJogXDiffPos := FALSE; AxisCmd_xJogXDiffNeg := FALSE;

IF AxisCmd_xPower AND NOT AxisCmd_xStopAll THEN
	CASE AxisCmd_eXMode OF
		0: (* 独立 *)
			AxisCmd_xJogM1Pos := HMI_xJogM1Pos;
			AxisCmd_xJogM1Neg := HMI_xJogM1Neg;
			AxisCmd_xJogM2Pos := HMI_xJogM2Pos;
			AxisCmd_xJogM2Neg := HMI_xJogM2Neg;
		1: (* 同步 *)
			AxisCmd_xJogXSyncPos := HMI_xJogXSyncPos;
			AxisCmd_xJogXSyncNeg := HMI_xJogXSyncNeg;
		2: (* 差速 *)
			AxisCmd_xJogXDiffPos := HMI_xJogXDiffPos;
			AxisCmd_xJogXDiffNeg := HMI_xJogXDiffNeg;
	END_CASE;
END_IF;

AxisCmd_xJogYPos := AxisCmd_xPower AND HMI_xJogYPos AND NOT xIlk_BlockYPlus AND NOT xIlk_BlockYWhenZ AND NOT AxisCmd_xStopAll;
AxisCmd_xJogYNeg := AxisCmd_xPower AND HMI_xJogYNeg AND NOT xIlk_BlockYNeg AND NOT xIlk_BlockYWhenZ AND NOT AxisCmd_xStopAll;
AxisCmd_xJogZPos := AxisCmd_xPower AND HMI_xJogZPos AND NOT xIlk_BlockZPlus AND NOT AxisCmd_xStopAll;
AxisCmd_xJogZNeg := AxisCmd_xPower AND HMI_xJogZNeg AND NOT xIlk_BlockZNeg AND NOT AxisCmd_xStopAll;
AxisCmd_xJogRPos := FALSE;
AxisCmd_xJogRNeg := FALSE;
AxisCmd_xHomeY := AxisCmd_xPower AND HMI_xHomeReqY AND NOT AxisCmd_xStopAll;
AxisCmd_xHomeZ := AxisCmd_xPower AND HMI_xHomeReqZ AND NOT AxisCmd_xStopAll;
AxisCmd_xHomeR := FALSE;

(* ---------- 报警号 ---------- *)
IF xEStopLatched OR NOT HMI_xEStop THEN
	iAlarmID := 1001; (* 急停 *)
ELSIF xFaultAggregate THEN
	iAlarmID := 1002; (* 驱动故障 *)
ELSIF (HMI_xJogYPos AND xIlk_BlockYPlus) OR (HMI_xJogYNeg AND xIlk_BlockYNeg)
	OR (HMI_xJogZPos AND xIlk_BlockZPlus) OR (HMI_xJogZNeg AND xIlk_BlockZNeg) THEN
	iAlarmID := 1003; (* 限位拒动 *)
ELSE
	iAlarmID := 0;
END_IF;

HMI_xLampEStop := xEStopLatched OR NOT HMI_xEStop;
HMI_xLampEnableOk := xPowerLatched AND xEnablePermit;
HMI_xLampFault := xFaultAggregate;
HMI_iAlarmShow := iAlarmID;

(* 读轴状态 / 实际位置 *)
fbReadStatus(Axis := Axis, Enable := TRUE);
fbReadPos(Axis := Axis, Enable := TRUE);

rActPos := fbReadPos.Position;
xStandstill := fbReadStatus.StandStill;
xMoving := fbReadStatus.DiscreteMotion OR fbReadStatus.ContinuousMotion;

(* 故障汇总：Errorstop + 各 FB.Error（不用 Axis.bError / Operational） *)
xFault := fbReadStatus.Errorstop
	OR fbReadStatus.Error
	OR fbPower.Error
	OR fbJog.Error
	OR fbStop.Error
	OR fbReset.Error;

(* 错误复位脉冲（来自停止钮长按 3s → AxisCmd_xResetFault） *)
fbReset(Axis := Axis, Execute := xResetFault);

(* 内部使能：请求使能且未停且非 Errorstop *)
xEnInternal := xEnable AND NOT xStop AND NOT fbReadStatus.Errorstop;

(* 功率级：Enable 恒 TRUE 以刷新；实际开/关看 bRegulatorOn/bDriveStart *)
fbPower(
	Axis := Axis,
	Enable := TRUE,
	bRegulatorOn := xEnInternal,
	bDriveStart := xEnInternal
);
(* Status=TRUE 表示轴可运动 *)
xPowered := fbPower.Status;

(* ---------- 运动仲裁 ---------- *)
IF xStop OR NOT xEnable OR fbReadStatus.Errorstop THEN
	(* 停止 / 禁使能 / 故障：停速度指令并减速停 *)
	fbJog(Axis := Axis, Execute := FALSE);
	fbHome(Axis := Axis, Execute := FALSE);
	fbStop(Axis := Axis, Execute := TRUE, Deceleration := rDec);

ELSIF xHome THEN
	(* 回零 *)
	fbStop(Axis := Axis, Execute := FALSE);
	fbJog(Axis := Axis, Execute := FALSE);
	fbHome(Axis := Axis, Execute := TRUE);

ELSIF xUseVelCmd THEN
	(* 成对速度模式：使用有符号 rVelCmd（来自 FB_XDiff） *)
	fbStop(Axis := Axis, Execute := FALSE);
	fbHome(Axis := Axis, Execute := FALSE);
	IF ABS(rVelCmd) > 1.0E-6 AND xPowered THEN
		fbJog(Axis := Axis, Execute := TRUE, Velocity := rVelCmd, Acceleration := rAcc, Deceleration := rDec);
	ELSE
		fbJog(Axis := Axis, Execute := FALSE);
	END_IF;

ELSIF xJogPos XOR xJogNeg THEN
	(* 独立 JOG *)
	fbStop(Axis := Axis, Execute := FALSE);
	fbHome(Axis := Axis, Execute := FALSE);
	IF xPowered THEN
		IF xJogPos THEN
			fbJog(Axis := Axis, Execute := TRUE, Velocity := ABS(rJogVel), Acceleration := rAcc, Deceleration := rDec);
		ELSE
			fbJog(Axis := Axis, Execute := TRUE, Velocity := -ABS(rJogVel), Acceleration := rAcc, Deceleration := rDec);
		END_IF;
	ELSE
		fbJog(Axis := Axis, Execute := FALSE);
	END_IF;

ELSE
	(* 空闲 *)
	fbJog(Axis := Axis, Execute := FALSE);
	fbHome(Axis := Axis, Execute := FALSE);
	fbStop(Axis := Axis, Execute := FALSE);
END_IF;

IF fbHome.Done THEN
	xHomed := TRUE;
END_IF;
